SELECT h.bom_id, h.parent_material_code, h.revision, l.line_no, l.component_material_code, COALESCE(m.display_name, '') AS component_name, l.quantity, l.uom, 1 AS level_no, CONCAT(h.parent_material_code, '>', l.component_material_code) AS path FROM mes_bom_header h JOIN mes_bom_line l ON l.bom_id = h.bom_id LEFT JOIN mes_genealogy_material m ON m.material_code = l.component_material_code WHERE h.parent_material_code = ? AND h.status = 'active' ORDER BY l.line_no
